prelude_js:
// 断脚趾实例（讲座原设定）：手术 0.95 / 并指固定 0.90 / 不处理 0.10，各拉一次得 1,1,0。
// 本片数字由 scratchpad/v12.py、v12b.py 独立核算：
//   依赖差距的界 Σ1/Δ = 20.000 + 1.176 = 21.176 —— 94.4% 来自只差 0.05 的那个臂
//   UCB 奖励项 sqrt(2 ln 3 / 1) = 1.4823；t=4 时 sqrt(2 ln4/2)=1.1774、sqrt(2 ln4/1)=1.6651
//   此刻选中坏臂的概率：UCB = 0，ε-贪心(ε=0.1) = ε/|A| = 0.0333
//   Thompson 采样的选择频率 = 「它是最优臂」的后验概率（40 万次蒙特卡洛，逐位吻合）
//   Even-Dar & Mansour 的初始化含 Π(1/α_i)：α=0.1 时 (1/0.1)^T = 10^T
//   MBIE-EB 的 β = (1/(1−γ))·sqrt( (1/2)·ln(2|S||A|m/δ) )；漏掉根号会差约 4.9 倍
function ucbBonus(t,n){return Math.sqrt(2*Math.log(t)/n);}
function mbieBeta(S,A,m,d,g){return (1/(1-g))*Math.sqrt(0.5*Math.log(2*S*A*m/d));}
function edmInit(alpha,T){return Math.pow(1/alpha,T);}

